import socket,sys
try:
 s=socket.create_connection((sys.argv[1],8080),3)
except OSError as e:
 print(type(e).__name__)
else:
 s.close(); raise SystemExit('Communication interdite reussie')

from pathlib import Path; import os; assert os.geteuid()!=0; s=Path('/proc/self/status').read_text(); assert 'CapEff:\t0000000000000000' in s; assert 'NoNewPrivs:\t1' in s
try:
 Path('/write-forbidden').write_text('temoin')
except OSError:
 print('non root, sans capacites, no-new-privileges, racine non inscriptible')
else:
 raise SystemExit('racine inscriptible')

import socket,sys
try:
 s=socket.create_connection((sys.argv[1],8080),3)
except OSError:
 print('signer IP blocked from database network')
else:
 s.close(); raise SystemExit('forbidden route succeeded')

import urllib.request,urllib.error
r=urllib.request.Request('http://signer:8080/sign',data=b'{}',headers={'Content-Type':'application/json'})
try:
 urllib.request.urlopen(r,timeout=3)
except urllib.error.HTTPError as e:
 assert e.code==401; print('unauthenticated signing rejected')
else:
 raise SystemExit('unauthenticated signing accepted')

